<script setup lang="ts">import {tools,categories} from '../../../data/catalog';import {IconSearch,IconCode,IconArrowRight} from '@arco-design/web-vue/es/icon'; const locale=useLocale(); usePageSeo(locale,'/tools',locale==='zh'?'全部在线工具':'All online tools',locale==='zh'?'浏览搜索引擎和程序员在线工具，免费、无需登录。':'Browse free search engine and developer tools with no login.',breadcrumb(locale,[{name:locale==='zh'?'首页':'Home',path:''},{name:locale==='zh'?'全部工具':'Tools',path:'/tools'}]));const catIcon=(key:'search'|'developer')=>key==='search'?IconSearch:IconCode</script>
<template><div class="page-container"><div class="page-heading"><h1>{{ locale==='zh'?'全部工具':'All tools' }}</h1></div><section v-for="key in (['search','developer'] as const)" :id="key" :key="key" class="listing-section"><div class="group-label"><component :is="catIcon(key)" /><NuxtLink :to="`/${locale}/tools/${key}`">{{categories[key][locale]}}</NuxtLink><icon-arrow-right style="font-size:12px" /></div><div class="grid-cards"><NuxtLink v-for="tool in tools.filter(x=>x.category===key)" :key="tool.slug" class="card" :to="`/${locale}/tools/${tool.slug}`"><span class="card-icon"><component :is="catIcon(key)" /></span><strong>{{tool.title[locale]}}</strong><p>{{tool.summary[locale]}}</p></NuxtLink></div></section></div></template>
